CREATE TABLE IF NOT EXISTS cog_users(id TEXT PRIMARY KEY,name TEXT NOT NULL,username TEXT NOT NULL UNIQUE COLLATE NOCASE,kind TEXT NOT NULL CHECK(kind IN ('operator','partner')),is_admin INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,password_hash TEXT NOT NULL,must_change INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cog_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES cog_users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON cog_sessions(user_id);
CREATE TABLE IF NOT EXISTS cog_login_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cog_plants(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,city TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cog_units(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES cog_plants(id),name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(plant_id,name));
CREATE TABLE IF NOT EXISTS cog_diary(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES cog_plants(id),kind TEXT NOT NULL CHECK(kind IN ('routine','abnormal')),text TEXT NOT NULL,occurred_at TEXT NOT NULL,author_id TEXT REFERENCES cog_users(id),author_name TEXT NOT NULL,created_at TEXT NOT NULL,archived_at TEXT,source_key TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS idx_diary_period ON cog_diary(occurred_at,plant_id);
CREATE TABLE IF NOT EXISTS cog_readings(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES cog_plants(id),unit_id TEXT NOT NULL REFERENCES cog_units(id),occurred_at TEXT NOT NULL,values_json TEXT NOT NULL,notes TEXT NOT NULL,author_id TEXT REFERENCES cog_users(id),author_name TEXT NOT NULL,created_at TEXT NOT NULL,archived_at TEXT,source_key TEXT UNIQUE);
CREATE UNIQUE INDEX IF NOT EXISTS idx_reading_unique ON cog_readings(unit_id,occurred_at) WHERE archived_at IS NULL;
CREATE TABLE IF NOT EXISTS cog_tickets(id TEXT PRIMARY KEY,number INTEGER UNIQUE NOT NULL,plant_id TEXT NOT NULL REFERENCES cog_plants(id),kind TEXT NOT NULL CHECK(kind IN ('verification','maintenance','inspection')),description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('open','in_progress','closed')),author_id TEXT REFERENCES cog_users(id),author_name TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,source_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS cog_ticket_users(ticket_id TEXT NOT NULL REFERENCES cog_tickets(id),user_id TEXT NOT NULL REFERENCES cog_users(id),PRIMARY KEY(ticket_id,user_id));
CREATE TABLE IF NOT EXISTS cog_movements(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES cog_tickets(id),text TEXT NOT NULL,status TEXT NOT NULL,author_id TEXT REFERENCES cog_users(id),author_name TEXT NOT NULL,created_at TEXT NOT NULL,source_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS cog_messages(id TEXT PRIMARY KEY,text TEXT NOT NULL,author_id TEXT NOT NULL REFERENCES cog_users(id),author_name TEXT NOT NULL,created_at TEXT NOT NULL,archived_at TEXT);
CREATE TABLE IF NOT EXISTS cog_outbox(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL UNIQUE REFERENCES cog_tickets(id),recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL,sent_at TEXT,error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS cog_audit(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL);
